    data class DistrictOption(
        val code: String,
        val name: String,
        val order: Int,
        val sectors: List<SectorOption>
    )

    data class SectorOption(
        val code: String,
        val name: String
    )

    fun getDistrictHierarchy(): List<DistrictOption> {
        val grouped = zones.groupBy { it.districtCode }
        return grouped.map { (distCode, zoneList) ->
            val distName = zoneList.first().districtName
            val num = distCode.removePrefix("PRAHA_").toIntOrNull() ?: 99
            DistrictOption(
                code = distCode,
                name = distName,
                order = num,
                sectors = zoneList.map { SectorOption(it.sectorCode, it.sectorName) }
            )
        }.sortedBy { it.order }
    }
